from math import gcd
from typing import Dict, List, Tuple


def fib(n: int) -> int:
    def _fd(k: int) -> Tuple[int, int]:
        if k == 0:
            return (0, 1)
        a, b = _fd(k >> 1)
        c = a * (2 * b - a)
        d = a * a + b * b
        return (d, c + d) if k & 1 else (c, d)
    return _fd(n)[0]


def factorize(m: int) -> Dict[int, int]:
    factors: Dict[int, int] = {}
    d = 2
    while d * d <= m:
        while m % d == 0:
            factors[d] = factors.get(d, 0) + 1
            m //= d
        d += 1 if d == 2 else 2
    if m > 1:
        factors[m] = factors.get(m, 0) + 1
    return factors


def primitive_divisors(n: int) -> List[int]:
    earlier = set()
    for k in range(1, n):
        earlier |= set(factorize(fib(k)))
    return sorted(p for p in factorize(fib(n)) if p not in earlier)


if __name__ == "__main__":
    print(f"{'n':>3} {'F(n)':>12} {'primitive prime divisors':<28}")
    for n in range(1, 31):
        pds = primitive_divisors(n)
        label = ", ".join(map(str, pds)) if pds else "(none -- exceptional)"
        print(f"{n:>3} {fib(n):>12} {label:<28}")

